// Workday calendar utilities
const avancarProximaHoraUtil = (date) => {
  let d = new Date(date);
  if (isNaN(d.getTime())) return new Date();
  const day = d.getDay();
  
  // Saturday -> Monday 08:00
  if (day === 6) {
    d.setDate(d.getDate() + 2);
    d.setHours(8, 0, 0, 0);
    return d;
  }
  // Sunday -> Monday 08:00
  if (day === 0) {
    d.setDate(d.getDate() + 1);
    d.setHours(8, 0, 0, 0);
    return d;
  }
  
  const hour = d.getHours();
  const minutes = d.getMinutes();
  const timeInMin = hour * 60 + minutes;
  
  if (timeInMin < 8 * 60) {
    d.setHours(8, 0, 0, 0);
  } else if (timeInMin >= 12 * 60 && timeInMin < 13 * 60 + 30) {
    d.setHours(13, 30, 0, 0);
  } else if (timeInMin >= 17 * 60 + 30) {
    d.setDate(d.getDate() + 1);
    d.setHours(8, 0, 0, 0);
    return avancarProximaHoraUtil(d);
  }
  return d;
};

const somarHorasUteis = (startDateObj, durationHours) => {
  let d = new Date(startDateObj);
  if (isNaN(d.getTime())) return new Date();
  let minutesToAdd = (parseInt(durationHours) || 1) * 60;
  
  d = avancarProximaHoraUtil(d);
  
  while (minutesToAdd > 0) {
    const hour = d.getHours();
    const minutes = d.getMinutes();
    const timeInMin = hour * 60 + minutes;
    
    if (timeInMin >= 8 * 60 && timeInMin < 12 * 60) {
      const remainingMorning = 12 * 60 - timeInMin;
      if (minutesToAdd <= remainingMorning) {
        d.setMinutes(d.getMinutes() + minutesToAdd);
        minutesToAdd = 0;
      } else {
        minutesToAdd -= remainingMorning;
        d.setHours(12, 0, 0, 0);
        d = avancarProximaHoraUtil(d);
      }
    } else if (timeInMin >= 13 * 60 + 30 && timeInMin < 17 * 60 + 30) {
      const remainingAfternoon = (17 * 60 + 30) - timeInMin;
      if (minutesToAdd <= remainingAfternoon) {
        d.setMinutes(d.getMinutes() + minutesToAdd);
        minutesToAdd = 0;
      } else {
        minutesToAdd -= remainingAfternoon;
        d.setHours(17, 30, 0, 0);
        d = avancarProximaHoraUtil(d);
      }
    } else {
      d = avancarProximaHoraUtil(d);
    }
  }
  return d;
};

// Helper to check if project / orcamento status is 'Em aberto' (case-insensitive)
const isSituacaoEmAberto = (val) => {
  if (val === undefined || val === null || val === '') return true;
  const s = String(val).trim().toLowerCase();
  return s === 'em aberto';
};

// Timeline offset calculation helpers
const getTimelineLayout = (daysList, dayWidthNormal, dayWidthWeekend) => {
  let currentOffset = 0;
  const dayLayouts = daysList.map((d) => {
    const isWeekend = d.getDay() === 0 || d.getDay() === 6;
    const width = isWeekend ? dayWidthWeekend : dayWidthNormal;
    const startPixel = currentOffset;
    currentOffset += width;
    return {
      date: d,
      width,
      startPixel,
      isWeekend
    };
  });
  const totalWidth = currentOffset;
  return { dayLayouts, totalWidth };
};

const getElapsedWorkingHours = (date) => {
  const d = new Date(date);
  if (isNaN(d.getTime())) return 0;
  const dayOfWeek = d.getDay();
  if (dayOfWeek === 0 || dayOfWeek === 6) return 0; // Weekend has 0 working hours

  const hours = d.getHours();
  const minutes = d.getMinutes();
  const timeInMin = hours * 60 + minutes;

  // Shift starts at 08:00 (480 mins)
  if (timeInMin <= 8 * 60) return 0;

  // Morning shift: 08:00 - 12:00 (480 - 720 mins)
  if (timeInMin <= 12 * 60) {
    return (timeInMin - 8 * 60) / 60;
  }

  // Lunch break: 12:00 - 13:30 (720 - 810 mins)
  if (timeInMin <= 13 * 60 + 30) {
    return 4; // All 4 hours of morning shift elapsed
  }

  // Afternoon shift: 13:30 - 17:30 (810 - 1050 mins)
  if (timeInMin <= 17 * 60 + 30) {
    return 4 + (timeInMin - (13 * 60 + 30)) / 60;
  }

  // After 17:30
  return 8; // All 8 working hours elapsed
};

const getPixelOffsetForDate = (date, dayLayouts) => {
  const dCopy = new Date(date);
  const time = dCopy.getTime();
  const idx = dayLayouts.findIndex(layout => {
    const dayStart = new Date(layout.date); dayStart.setHours(0, 0, 0, 0);
    const dayEnd = new Date(layout.date); dayEnd.setHours(23, 59, 59, 999);
    return time >= dayStart.getTime() && time <= dayEnd.getTime();
  });
  if (idx === -1) {
    if (dayLayouts.length === 0) return 0;
    if (time < new Date(dayLayouts[0].date).setHours(0, 0, 0, 0)) return 0;
    return dayLayouts[dayLayouts.length - 1].startPixel + dayLayouts[dayLayouts.length - 1].width;
  }
  const layout = dayLayouts[idx];
  if (layout.isWeekend) {
    return layout.startPixel;
  }
  const hElapsed = getElapsedWorkingHours(dCopy);
  return layout.startPixel + (hElapsed / 8) * layout.width;
};

const formatarDiaGantt = (dateObj) => {
  const day = dateObj.getDate();
  let weekday = dateObj.toLocaleDateString('pt-BR', { weekday: 'short' });
  weekday = weekday.replace('.', '');
  weekday = weekday.charAt(0).toUpperCase() + weekday.slice(1);
  return `${day}-${weekday}`;
};

// Global formatting and conversion helpers
const formatPtBr = (valStr) => {
  if (!valStr) return '';
  const digitsOnly = String(valStr).replace(/\D/g, '');
  if (!digitsOnly) return '';
  const numberValue = parseFloat(digitsOnly) / 100;
  return numberValue.toLocaleString('pt-BR', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2
  });
};

const formatInitialPrice = (val) => {
  if (val === null || val === undefined || val === '') return '';
  if (typeof val === 'string' && val.includes(',')) {
    const parsed = parsePtBrToFloat(val);
    return parsed.toLocaleString('pt-BR', {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2
    });
  }
  const num = Number(val);
  if (isNaN(num)) return '';
  return num.toLocaleString('pt-BR', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2
  });
};

const parsePtBrToFloat = (formattedStr) => {
  if (typeof formattedStr === 'number') return formattedStr;
  if (!formattedStr) return 0.0;
  const cleanStr = String(formattedStr).replace(/\./g, '').replace(',', '.');
  const parsed = parseFloat(cleanStr);
  return isNaN(parsed) ? 0.0 : parsed;
};

const formatDecimalPtBr = (val) => {
  const num = Number(val);
  if (val === null || val === undefined || isNaN(num)) return '0,00';
  return num.toLocaleString('pt-BR', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2
  });
};

const valorPorExtenso = (valor) => {
  if (valor === undefined || valor === null || isNaN(valor)) return 'Zero reais';
  const val = Math.abs(Number(valor));
  if (val === 0) return 'Zero reais';

  const unidades = ['', 'um', 'dois', 'três', 'quatro', 'cinco', 'seis', 'sete', 'oito', 'nove'];
  const especiais = ['dez', 'onze', 'doze', 'treze', 'quatorze', 'quinze', 'dezesseis', 'dezessete', 'dezoito', 'dezenove'];
  const dezenas = ['', '', 'vinte', 'trinta', 'quarenta', 'cinquenta', 'sessenta', 'setenta', 'oitenta', 'noventa'];
  const centenas = ['', 'cento', 'duzentos', 'trezentos', 'quatrocentos', 'quinhentos', 'seiscentos', 'setecentos', 'oitocentos', 'novecentos'];

  const converterCentena = (n) => {
    if (n === 100) return 'cem';
    const c = Math.floor(n / 100);
    const d = Math.floor((n % 100) / 10);
    const u = n % 10;
    const parts = [];
    if (c > 0) parts.push(centenas[c]);
    if (d === 1) {
      parts.push(especiais[u]);
    } else {
      if (d > 1) parts.push(dezenas[d]);
      if (u > 0) parts.push(unidades[u]);
    }
    return parts.join(' e ');
  };

  const parteInteira = Math.floor(val);
  const centavos = Math.round((val - parteInteira) * 100);

  if (parteInteira === 0 && centavos === 0) return 'Zero reais';

  let resultadoReais = '';
  if (parteInteira > 0) {
    const bilhoes = Math.floor(parteInteira / 1000000000) % 1000;
    const milhoes = Math.floor(parteInteira / 1000000) % 1000;
    const milhares = Math.floor(parteInteira / 1000) % 1000;
    const unidadesGrupo = parteInteira % 1000;

    const partes = [];
    if (bilhoes > 0) {
      partes.push(`${converterCentena(bilhoes)} ${bilhoes === 1 ? 'bilhão' : 'bilhões'}`);
    }
    if (milhoes > 0) {
      partes.push(`${converterCentena(milhoes)} ${milhoes === 1 ? 'milhão' : 'milhões'}`);
    }
    if (milhares > 0) {
      if (milhares === 1) {
        partes.push('mil');
      } else {
        partes.push(`${converterCentena(milhares)} mil`);
      }
    }
    if (unidadesGrupo > 0) {
      partes.push(converterCentena(unidadesGrupo));
    }

    const textoReais = partes.join(' e ');
    resultadoReais = `${textoReais} ${parteInteira === 1 ? 'real' : 'reais'}`;
  }

  let resultadoCentavos = '';
  if (centavos > 0) {
    const textoCentavos = converterCentena(centavos);
    resultadoCentavos = `${textoCentavos} ${centavos === 1 ? 'centavo' : 'centavos'}`;
  }

  let final = '';
  if (resultadoReais && resultadoCentavos) {
    final = `${resultadoReais} e ${resultadoCentavos}`;
  } else if (resultadoReais) {
    final = resultadoReais;
  } else if (resultadoCentavos) {
    final = resultadoCentavos;
  }

  return final ? final.charAt(0).toUpperCase() + final.slice(1) : 'Zero reais';
};

// Utilitário global para resolução de URL de imagens e anexos da API
export const getMediaUrl = (imgPath) => {
  if (!imgPath) return '';
  if (imgPath.startsWith('http://') || imgPath.startsWith('https://') || imgPath.startsWith('blob:') || imgPath.startsWith('data:')) return imgPath;
  const clean = imgPath.startsWith('/') ? imgPath.substring(1) : imgPath;
  const apiRoot = (import.meta.env.VITE_API_URL || '').replace(/\/api\/?$/, '');
  return apiRoot ? `${apiRoot}/${clean}` : `/${clean}`;
};

// Cache para parâmetros da empresa utilizados na geração de impressões e documentos
let cachedEmpresaParams = null;
let lastEmpresaParamsFetch = 0;

export const getEmpresaParametros = async () => {
  const now = Date.now();
  if (cachedEmpresaParams && (now - lastEmpresaParamsFetch < 30000)) {
    return cachedEmpresaParams;
  }
  try {
    const res = await api.get('/parametros-empresa');
    if (Array.isArray(res.data)) {
      const map = {};
      res.data.forEach(p => {
        if (p.chave) {
          map[p.chave.toUpperCase()] = p.conteudo || '';
        }
      });
      cachedEmpresaParams = map;
      lastEmpresaParamsFetch = now;
      return map;
    }
  } catch (err) {
    console.error('Erro ao carregar parâmetros da empresa para documentos:', err);
  }
  return cachedEmpresaParams || {};
};

